mapper.select:
select distinct a.id applyId , a.type applyType, d.id detailId , d.GROUP_ID groupId, r.FROM_USER_TYPE fromUserType from xuncha_checked_apply_info a join xuncha_checked_apply_detail d on a.id = d.APPLY_ID join xuncha_checked_exam_relation r on (a.id = r.APPLY_ID and d.id = r.DETAIL_ID) where a.is_del = '0' and a.APPROVE_STATUS = '2' and d.GROUP_ID in(select d.GROUP_ID from xuncha_checked_apply_detail d where r.status='1' and d.ID in (select distinct DETAIL_ID from xuncha_checked_exam_relation where status = '1' and LAST_TIME > now()) )
and DATE_FORMAT( r.LAST_TIME, '%Y%m%d%H%i' ) > #{startTime}
and DATE_FORMAT( r.LAST_TIME, '%Y%m%d%H%i' ) <= #{endTime}

select s.TO_USER_ID toUserId, su.nick_name toUserName , pi.LABEL_KEY userTypeId, convert(IFNULL(sum(s.scope)/count(s.FROM_ID),0),decimal(15,2)) scope
from xuncha_checked_apply_detail d
join xuncha_checked_exam_relation r on d.id = r.DETAIL_ID
join (select es.FROM_ID , es.TO_USER_ID , SUM(es.scope) scope
	from xuncha_checked_exam_scope es
	
		
			and es.APPLY_ID = #{applyId}
		
		
			and es.SCOPE_TYPE_ID = #{fromUserType}
		
	
	group by es.FROM_ID , es.TO_USER_ID
) s on r.id = s.FROM_ID
join sys_user su on su.user_name = s.TO_USER_ID
left join (select gpi.GROUP_ID , gpi.PERSONNEL_ID , gpi.`STATUS` , gpi.LABEL_KEY from xuncha_task_group_person_info gpi
	
		
			and gpi.LABEL_KEY in ('0','1')
		
		
			and gpi.LABEL_KEY not in ('0','1')
			union
			select fgr.CHECK_GROUP_ID GROUP_ID , fpi.PERSONNEL_ID , '1' `STATUS`, '' LABEL_KEY from xuncha_fly_person_info fpi
			join xuncha_check_fly_group_relation fgr on fpi.FLY_GROUP_ID = fgr.FLY_GROUP_ID
		
	
)pi on (pi.GROUP_ID = d.GROUP_ID and pi.PERSONNEL_ID = s.TO_USER_ID)

	pi.`STATUS` = '1'
	
		and r.APPLY_ID = #{applyId}
	
	
		and r.DETAIL_ID = #{detailId}
	
	
		and r.FROM_USER_TYPE = #{fromUserType}
	

group by  s.TO_USER_ID , su.nick_name  , pi.LABEL_KEY

mapper.update:
update xuncha_checked_apply_detail
CREATED_BY = #{createdBy}, CREATED_TIME = #{createdTime}, UPDATED_BY = #{updatedBy}, UPDATED_TIME = #{updatedTime}, APPLY_ID = #{applyId}, GROUP_ID = #{groupId}, GROUP_LEADER_STATUS = #{groupLeaderStatus}, GROUP_LEADER_SCOPE = #{groupLeaderScope}, CRUISING_STATUS = #{cruisingStatus}, CRUISING_SCOPE = #{cruisingScope}, TO_CRUISING_STATUS = #{toCruisingStatus}, TO_CRUISING_SCOPE = #{toCruisingScope}, GROUP_PER_STATUS = #{groupPerStatus}, GROUP_LEADER_LAST_TIME = #{groupLeaderLastTime}, GROUP_LEADER_REMARK = #{groupLeaderRemark}, CRUISING_LAST_TIME = #{cruisingLastTime}, CRUISING_REMARK = #{cruisingRemark}, TO_CRUISING_LAST_TIME = #{toCruisingLastTime}, TO_CRUISIN_REMARK = #{toCruisinRemark},
where ID = #{detailId}

update xuncha_checked_pro_result
CREATED_BY = #{createdBy}, CREATED_TIME = #{createdTime}, UPDATED_BY = #{updatedBy}, UPDATED_TIME = #{updatedTime}, TO_USER_ID = #{toUserId}, TO_USER_NAME = #{toUserName}, SCOPE = #{scope}, LEVEL_ID = #{levelId}, GROUP_ID = #{groupId}, TO_USER_TYPE_ID = #{toUserTypeId}, SCOPE_TYPE = #{scopeType}, YEAR = #{year}, BATCH_ID = #{batchId},
where ID = #{id}

mapper.select:
select * from xuncha_checked_pro_result r

	
		and r.group_id = #{groupId}
	
	
		and r.scope_type = #{scopeType}

		select convert(IFNULL(sum(a.scope)/count(a.FROM_ID),0),decimal(15,2)) scope from (
			select s.FROM_ID , sum(s.SCOPE) SCOPE from xuncha_checked_exam_scope s
			
				
					and s.SCOPE_TYPE_ID = #{fromUserType}
				
				
					and s.TO_USER_ID = #{groupId}
				
				
					and s.APPLY_ID = #{applyId}
				
			
			group by s.FROM_ID
		) a

